const crypto = require('crypto');

/**
 * Encrypt the data with the key using CBC mode.
 * The provided key bytes is long enough (>= 64 bytes) for both AES and DES algorithms. Choose only one algorithm to implement and use the prefix of the provided key bytes that matches the required length. Do NOT choose the algorithm based on the length of the key.
 * Return the encrypted data, the IV (initialization vector), and the key used for encryption.
 *
 * @param {Buffer} key - The bytes to generate the encryption key.
 * @param {Buffer} data - The data to encrypt.
 * @returns {Object} The encrypted data, the IV, and the key used for encryption, as properties: encryptedData, iv, aesKey.
 */
function encryptData(key, data) {
    // Choose AES algorithm for implementation as specified.
    // AES-256-CBC requires a 32-byte key and a 16-byte IV.
    const algorithm = 'aes-256-cbc';
    const aesKeyLength = 32; // 256 bits = 32 bytes for AES key
    const ivLength = 16;     // 128 bits = 16 bytes for AES block size (and IV length)

    // Use the prefix of the provided key bytes that matches the required AES key length.
    // The docstring guarantees the input 'key' is long enough (>= 64 bytes),
    // so slicing 32 bytes from the beginning is safe.
    const aesKey = key.slice(0, aesKeyLength);

    // Generate a cryptographically strong random Initialization Vector (IV) for CBC mode.
    // The IV must be unique for each encryption operation with the same key to ensure security.
    const iv = crypto.randomBytes(ivLength);

    // Create the cipher object using the chosen algorithm, the derived AES key, and the generated IV.
    const cipher = crypto.createCipheriv(algorithm, aesKey, iv);

    // Encrypt the data.
    // The cipher.update() method processes the main part of the data.
    // The cipher.final() method processes any remaining data and handles padding.
    // Both methods return a Buffer, which are concatenated to form the complete encrypted data.
    const encryptedData = Buffer.concat([cipher.update(data), cipher.final()]);

    // Return the encrypted data, the IV, and the AES key used for encryption
    // as properties of an object, as specified in the docstring.
    return {
        encryptedData: encryptedData,
        iv: iv,
        aesKey: aesKey
    };
}
